// Historical node metadata seed retained by dwarf-skill-expansion.js and isolated fixtures.
// Production selects the expanded tree through race-registry; schema4 rejects old saves, without migration.
const freeze=x=>{if(x&&typeof x==='object'){Object.values(x).forEach(freeze);Object.freeze(x);}return x;};
export const SKILL_TREE_DEFINITION=freeze({"id":"dwarf-skill-tree-99-candidate-v1","status":"reviewed-initial-v036","nodes":[{"id":"fracture_strike","name":"裂岩击","kind":"active","cost":3,"requires":[]},{"id":"fault_sweep","name":"断层横扫","kind":"active","cost":5,"requires":["fracture_strike"]},{"id":"breach_followup","name":"破隙追击","kind":"active","cost":7,"requires":["fracture_strike"]},{"id":"axe_fervor","name":"狂斧","kind":"passive","cost":5,"requires":["fault_sweep"]},{"id":"hammer_penetration","name":"重锤穿甲","kind":"passive","cost":5,"requires":["breach_followup"]},{"id":"ember_brand","name":"熔火烙印","kind":"active","cost":3,"requires":[]},{"id":"furnace_wave","name":"炉焰迸发","kind":"active","cost":5,"requires":["ember_brand"]},{"id":"cinder_barrage","name":"余烬连击","kind":"active","cost":7,"requires":["furnace_wave"]},{"id":"fire_affinity","name":"炉火亲和","kind":"passive","cost":5,"requires":["ember_brand"]},{"id":"iron_vigil","name":"铁幕守势","kind":"active","cost":3,"requires":[]},{"id":"bastion_blow","name":"守势重击","kind":"active","cost":6,"requires":["iron_vigil"]},{"id":"repelling_wave","name":"震退波","kind":"active","cost":6,"requires":["iron_vigil"]},{"id":"shield_reserve","name":"铁壁余力","kind":"passive","cost":5,"requires":["iron_vigil"]},{"id":"mountain_vitality","name":"山岩体魄","kind":"passive","cost":4,"requires":[]},{"id":"anvil_cry","name":"战炉怒吼","kind":"active","cost":4,"requires":[]},{"id":"breaking_intercept","name":"截势","kind":"active","cost":5,"requires":[]},{"id":"furnace_etch","name":"熔蚀刻印","kind":"active","cost":5,"requires":[]},{"id":"scatter_ash","name":"撒灰","kind":"active","cost":5,"requires":[]},{"id":"forge_breath","name":"回炉息","kind":"active","cost":3,"requires":[]},{"id":"purifying_bulwark","name":"净炉壁垒","kind":"active","cost":5,"requires":[]},{"id":"forged_resilience","name":"百锻韧性","kind":"passive","cost":3,"requires":[]}]});
export function skillTreeNode(id){return typeof id==='string'?SKILL_TREE_DEFINITION.nodes.find(n=>n.id===id)??null:null;}

if(SKILL_TREE_DEFINITION.nodes.reduce((sum,n)=>sum+n.cost,0)!==99||SKILL_TREE_DEFINITION.nodes.filter(n=>n.kind==='active').length!==15||SKILL_TREE_DEFINITION.nodes.filter(n=>n.kind==='passive').length!==6)throw new Error('Invalid frozen99 skill-tree snapshot');
